package main

import (
	"context"
	"errors"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"
)

func env(name, fallback string) string {
	if v := os.Getenv(name); v != "" {
		return v
	}
	return fallback
}
func config() (string, string, string, time.Duration, error) {
	secret := os.Getenv("AUTH_SECRET")
	if len(secret) < 32 {
		return "", "", "", 0, errors.New("AUTH_SECRET must be at least 32 bytes")
	}
	issuer := env("AUTH_ISSUER", "auth-service")
	address := env("AUTH_ADDR", ":8080")
	ttlText := env("AUTH_TTL", "15m")
	ttl, err := time.ParseDuration(ttlText)
	if err != nil || ttl <= 0 {
		return "", "", "", 0, errors.New("AUTH_TTL must be a positive duration")
	}
	return secret, issuer, address, ttl, nil
}
func main() {
	secret, issuer, address, ttl, err := config()
	if err != nil {
		log.Fatal(err)
	}
	tokens := TokenManager{[]byte(secret), issuer, ttl}
	service := &AuthService{NewUserRepository(), tokens}
	mux := http.NewServeMux()
	mux.HandleFunc("POST /register", service.registerHandler)
	mux.HandleFunc("POST /login", service.loginHandler)
	mux.Handle("GET /me", authMiddleware(tokens, http.HandlerFunc(meHandler)))
	server := &http.Server{Addr: address, Handler: mux, ReadTimeout: 10 * time.Second, ReadHeaderTimeout: 5 * time.Second, WriteTimeout: 10 * time.Second, IdleTimeout: 60 * time.Second}
	stop, cancel := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer cancel()
	go func() {
		log.Printf("auth service listening on %s", address)
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Printf("server error: %v", err)
		}
	}()
	<-stop.Done()
	shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer shutdownCancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		log.Printf("shutdown error: %v", err)
	}
}
package main

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
)

type credentials struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}
type apiError struct {
	Error struct {
		Code    string `json:"code"`
		Message string `json:"message"`
	} `json:"error"`
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}
func writeError(w http.ResponseWriter, status int, code, message string) {
	var e apiError
	e.Error.Code, e.Error.Message = code, message
	writeJSON(w, status, e)
}
func decodeCredentials(r *http.Request) (credentials, error) {
	var c credentials
	if err := json.NewDecoder(r.Body).Decode(&c); err != nil {
		return c, err
	}
	return c, nil
}

func (s *AuthService) registerHandler(w http.ResponseWriter, r *http.Request) {
	c, err := decodeCredentials(r)
	if err != nil {
		writeError(w, 400, "invalid_json", "request body must be valid JSON")
		return
	}
	u, err := s.Register(c.Email, c.Password)
	if err != nil {
		code := "invalid_request"
		status := 400
		if errors.Is(err, errors.New("email already registered")) || err.Error() == "email already registered" {
			code, status = "conflict", 409
		}
		writeError(w, status, code, err.Error())
		return
	}
	writeJSON(w, 201, map[string]any{"id": u.ID, "email": u.Email})
}
func (s *AuthService) loginHandler(w http.ResponseWriter, r *http.Request) {
	c, err := decodeCredentials(r)
	if err != nil {
		writeError(w, 400, "invalid_json", "request body must be valid JSON")
		return
	}
	token, _, err := s.Login(c.Email, c.Password)
	if err != nil {
		writeError(w, 401, "invalid_credentials", "invalid email or password")
		return
	}
	writeJSON(w, 200, map[string]string{"access_token": token, "token_type": "Bearer"})
}

type contextKey string

const claimsKey contextKey = "claims"

func authMiddleware(tm TokenManager, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		raw, err := parseBearer(r.Header.Get("Authorization"))
		if err != nil {
			writeError(w, 401, "unauthorized", "Bearer token required")
			return
		}
		claims, err := tm.Verify(raw, nowUTC())
		if err != nil {
			writeError(w, 401, "unauthorized", "invalid or expired token")
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), claimsKey, claims)))
	})
}
func meHandler(w http.ResponseWriter, r *http.Request) {
	c := r.Context().Value(claimsKey).(tokenClaims)
	writeJSON(w, 200, map[string]string{"id": c.Subject, "email": c.Email})
}
